<template>
  <ion-page class="owner-page">
    <AppHeader variant="owner" title="PoliLand Kairagi" :show-back="false" />
    <ion-content class="owner-content">
      <main class="owner-shell">
        <div class="report-tabs"><button v-for="item in reportTabs" :key="item.value" type="button" :class="{active:activeTab===item.value}" @click="activeTab=item.value"><ion-icon :icon="item.icon" /><span>{{ item.label }}</span></button></div>

        <section class="panel summary-panel">
          <div class="panel-heading"><span class="accent-icon"><ion-icon :icon="barChartOutline" /></span><div><h1>{{ activeTab === 'sales' ? 'Ringkasan Penjualan' : activeTab === 'payments' ? 'Ringkasan Pembayaran' : 'Ringkasan Pemasaran' }}</h1><p>Rekapitulasi berdasarkan periode</p></div><label class="year-picker">Tahun <select v-model.number="year"><option v-for="option in years" :key="option" :value="option">{{ option }}</option></select><ion-icon :icon="chevronDownOutline" /></label></div>
          <div class="summary-grid"><article><span class="summary-icon green"><ion-icon :icon="mapOutline" /></span><strong>{{ lots.length }}</strong><small>Total Kavling</small></article><article><span class="summary-icon mint"><ion-icon :icon="homeOutline" /></span><strong>{{ availableCount }}</strong><small>Tersedia</small></article><article><span class="summary-icon orange"><ion-icon :icon="calendarOutline" /></span><strong>{{ bookingCount }}</strong><small>Booking</small></article><article><span class="summary-icon red"><ion-icon :icon="checkmarkCircleOutline" /></span><strong>{{ soldCount }}</strong><small>Terjual</small></article></div>
        </section>

        <section class="panel chart-panel">
          <div class="panel-heading"><span class="accent-icon blue"><ion-icon :icon="barChartOutline" /></span><div><h2>{{ activeTab === 'payments' ? 'Pembayaran Periode' : activeTab === 'marketing' ? 'Konsumen Baru Periode' : 'Penjualan Periode' }}</h2><p>{{ activeTab === 'payments' ? 'Jumlah pembayaran terkonfirmasi per bulan' : activeTab === 'marketing' ? 'Pendaftaran calon pembeli baru per bulan' : 'Jumlah kavling yang terjual dan terbooking setiap bulan' }}</p></div></div>
          <div class="legend"><template v-if="activeTab==='sales'"><i class="booking" />Booking <i class="sold" />Terjual</template><template v-else-if="activeTab==='payments'"><i class="sold" />Transaksi</template><template v-else><i class="sold" />Konsumen Baru</template></div>
          <div class="chart"><div v-for="(month,index) in months" :key="month" class="chart-col"><div class="bars"><i v-if="activeTab==='sales'" class="booking" :style="{height:`${height(monthlyBookings[index])}%`}" /><i class="sold" :style="{height:`${height(activeTab==='payments'?monthlyPayments[index]:activeTab==='marketing'?monthlyCustomers[index]:monthlySold[index])}%`}" /></div><small>{{ month }}</small></div></div>
        </section>

        <section class="panel table-panel">
          <div class="panel-heading"><span class="accent-icon peach"><ion-icon :icon="receiptOutline" /></span><div><h2>{{ activeTab === 'payments' ? 'Daftar Transaksi Pembayaran' : activeTab === 'marketing' ? 'Daftar Calon Pembeli' : 'Daftar Transaksi Penjualan' }}</h2><p>Daftar data pada periode yang dipilih</p></div></div>
          <p v-if="loading" class="load-message">Memuat data laporan...</p>
          <label class="search"><ion-icon :icon="searchOutline" /><input v-model="search" type="search" :placeholder="activeTab==='payments'?'Cari nama pembeli atau kategori pembayaran...':activeTab==='marketing'?'Cari nama atau asal calon pembeli...':'Cari nama pembeli atau kode kavling...'" /></label>
          <div class="table-wrap"><table><thead><tr v-if="activeTab==='payments'"><th>TANGGAL</th><th>KATEGORI</th><th>NAMA PEMBELI</th><th>JUMLAH</th><th>STATUS</th></tr><tr v-else-if="activeTab==='marketing'"><th>TANGGAL</th><th>CALON PEMBELI</th><th>ASAL</th><th>STATUS</th></tr><tr v-else><th>TANGGAL</th><th>KAVLING</th><th>NAMA PEMBELI</th><th>BLOK</th><th>STATUS</th></tr></thead><tbody>
            <tr v-for="row in visibleRows" :key="row.id"><template v-if="activeTab==='payments'"><td>{{ dateLabel(row.date) }}</td><td>{{ row.category }}</td><td>{{ row.customer }}</td><td>{{ currency(row.amount) }}</td><td><span class="state-chip" :class="row.status==='Confirmed'?'confirmed':'pending'">{{ row.status }}</span></td></template><template v-else-if="activeTab==='marketing'"><td>{{ dateLabel(row.date) }}</td><td>{{ row.customer }}</td><td>{{ row.block }}</td><td><span class="state-chip confirmed">Konsumen Baru</span></td></template><template v-else><td>{{ dateLabel(row.date) }}</td><td class="lot-number">{{ row.lot }}</td><td>{{ row.customer }}</td><td>{{ row.block }}</td><td><span class="state-chip" :class="row.sold?'sold':'booking'">{{ row.sold?'Terjual':'Booking' }}</span></td></template></tr>
            <tr v-if="!visibleRows.length"><td :colspan="activeTab==='payments'?5:5" class="empty">Tidak ada data untuk pencarian ini.</td></tr>
          </tbody></table></div>
          <p class="table-caption">Menampilkan {{ visibleRows.length }} dari {{ filteredRows.length }} data</p>
          <nav v-if="pageCount>1" class="pagination"><button :disabled="page===1" aria-label="Sebelumnya" @click="page--">‹</button><button v-for="n in pageCount" :key="n" :class="{active:page===n}" @click="page=n">{{ n }}</button><button :disabled="page===pageCount" aria-label="Berikutnya" @click="page++">›</button></nav>
        </section>

        <section v-if="activeTab==='sales'" class="panel block-panel"><div class="panel-heading"><span class="accent-icon peach"><ion-icon :icon="pieChartOutline" /></span><div><h2>Penjualan Per Blok</h2><p>Jumlah kavling terjual dan terbooking setiap blok</p></div></div><div class="legend"><i class="booking" />Booking <i class="sold" />Terjual</div><div class="block-chart"><div v-for="entry in blockSales" :key="entry.name" class="block-column"><div class="bars"><i class="booking" :style="{height:`${height(entry.booking)}%`}"/><i class="sold" :style="{height:`${height(entry.sold)}%`}"/></div><small>{{ entry.name }}</small></div><p v-if="!blockSales.length" class="empty">Data blok belum tersedia.</p></div></section>

        <section v-if="activeTab==='sales'" class="panel value-panel"><div class="panel-heading"><span class="accent-icon peach"><ion-icon :icon="trendingUpOutline" /></span><div><h2>Nilai Penjualan Periode</h2><p>Total nilai penjualan setiap bulan</p></div></div><div class="value-chart"><div v-for="(value,index) in monthlyValue" :key="index" class="value-col" :title="`${months[index]}: ${currency(value)}`"><i :style="{bottom:`${valueHeight(value)}%`}"/><small>{{ months[index] }}</small></div></div></section>

        <section class="panel export-panel"><div class="panel-heading"><span class="accent-icon mint"><ion-icon :icon="documentTextOutline" /></span><div><h2>Unduh Data</h2><p>Simpan data laporan atau cetak sebagai PDF sesuai filter yang dipilih.</p></div></div><button type="button" class="export-button" @click="exportCsv"><ion-icon :icon="downloadOutline" />Unduh Laporan CSV</button><button type="button" class="pdf-button" @click="printReport"><ion-icon :icon="documentTextOutline" />Cetak / Simpan PDF</button></section>
        <p v-if="error" class="error-state">{{ error }} <button type="button" @click="loadData">Coba lagi</button></p>
      </main>
    </ion-content>
    <MobileTabBar variant="owner" />
  </ion-page>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { IonContent, IonIcon, IonPage } from '@ionic/vue'
import { barChartOutline, calendarOutline, checkmarkCircleOutline, chevronDownOutline, documentTextOutline, downloadOutline, homeOutline, mapOutline, pieChartOutline, receiptOutline, searchOutline, trendingUpOutline, walletOutline } from 'ionicons/icons'
import AppHeader from '@/components/common/AppHeader.vue'
import MobileTabBar from '@/components/common/MobileTabBar.vue'
import { supabase } from '@/services/config/supabase'
import { getLots, type SiteplanLot } from '@/services/siteplanService'
import { normalizeLotStatus } from '@/utils/siteplan'

type Transaction={id:number;lot_id:number;customer_id:number;status:string;final_price:number|string|null;created_at:string|null;booking_date:string|null;sold_date:string|null}
type Customer={id:number;full_name:string|null;address:string|null;created_at:string|null}
type Payment={id:number;amount:number|string|null;status:string;payment_category:string|null;created_at:string|null;payment_date:string|null;customer_id:number|null}
const months=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des']
const reportTabs=[{value:'sales',label:'Laporan Penjualan',icon:barChartOutline},{value:'payments',label:'Laporan Pembayaran',icon:walletOutline},{value:'marketing',label:'Laporan Pemasaran',icon:homeOutline}]
const route=useRoute()
const initialTab=typeof route.query.tab==='string'&&reportTabs.some(item=>item.value===route.query.tab)?route.query.tab:'sales'
const activeTab=ref(initialTab),year=ref(new Date().getFullYear()),search=ref(''),page=ref(1),loading=ref(true),error=ref('')
const lots=ref<SiteplanLot[]>([]),transactions=ref<Transaction[]>([]),customers=ref<Customer[]>([]),payments=ref<Payment[]>([])
const isSold=(value:string)=>['sold','terjual','closed','completed'].includes(value.toLowerCase())
function printReport(){window.print()}
const isBooking=(value:string)=>['booking','booked','reserved','dibooking'].some(status=>value.toLowerCase().includes(status))
const years=computed(()=>{const result=new Set<number>([new Date().getFullYear()]);transactions.value.forEach(row=>{const date=row.sold_date||row.created_at;if(date)result.add(new Date(date).getFullYear())});return [...result].sort((a,b)=>b-a)})
const availableCount=computed(()=>lots.value.filter(lot=>normalizeLotStatus(lot.status)==='available').length),bookingCount=computed(()=>lots.value.filter(lot=>normalizeLotStatus(lot.status)==='booking').length),soldCount=computed(()=>lots.value.filter(lot=>normalizeLotStatus(lot.status)==='sold').length)
const monthlyBookings=computed(()=>months.map((_,month)=>transactions.value.filter(row=>{const date=row.booking_date||row.created_at;return isBooking(row.status)&&date&&new Date(date).getFullYear()===year.value&&new Date(date).getMonth()===month}).length))
const monthlySold=computed(()=>months.map((_,month)=>transactions.value.filter(row=>{const date=row.sold_date||row.created_at;return isSold(row.status)&&date&&new Date(date).getFullYear()===year.value&&new Date(date).getMonth()===month}).length))
const monthlyPayments=computed(()=>months.map((_,month)=>payments.value.filter(row=>{const date=row.payment_date||row.created_at;return row.status==='Confirmed'&&date&&new Date(date).getFullYear()===year.value&&new Date(date).getMonth()===month}).length))
const monthlyCustomers=computed(()=>months.map((_,month)=>customers.value.filter(row=>row.created_at&&new Date(row.created_at).getFullYear()===year.value&&new Date(row.created_at).getMonth()===month).length))
const monthlyValue=computed(()=>months.map((_,month)=>transactions.value.reduce((sum,row)=>{const date=row.sold_date||row.created_at;return isSold(row.status)&&date&&new Date(date).getFullYear()===year.value&&new Date(date).getMonth()===month?sum+Number(row.final_price||0):sum},0)))
const blockSales=computed(()=>{const map=new Map<string,{name:string;booking:number;sold:number}>();transactions.value.forEach(row=>{const date=row.sold_date||row.booking_date||row.created_at;if(!date||new Date(date).getFullYear()!==year.value||(!isBooking(row.status)&&!isSold(row.status)))return;const lot=lots.value.find(item=>Number(item.id)===row.lot_id);const name=lot?.blocks?.code||lot?.blocks?.name||'—';const entry=map.get(name)||{name,booking:0,sold:0};if(isSold(row.status))entry.sold++;else entry.booking++;map.set(name,entry)});return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'id-ID'))})
const salesRows=computed(()=>transactions.value.filter(row=>{const date=row.sold_date||row.booking_date||row.created_at;return date&&new Date(date).getFullYear()===year.value&&(isSold(row.status)||isBooking(row.status))}).map(row=>{const lot=lots.value.find(item=>Number(item.id)===row.lot_id);const sold=isSold(row.status);return{id:`sale-${row.id}`,date:row.sold_date||row.booking_date||row.created_at||'',lot:lot?.lot_number||`#${row.lot_id}`,customer:customers.value.find(item=>item.id===row.customer_id)?.full_name||'—',block:lot?.blocks?.code||lot?.blocks?.name||'—',sold,amount:Number(row.final_price||0),category:'Penjualan',status:sold?'Terjual':'Booking'}}))
const paymentRows=computed(()=>payments.value.filter(row=>{const date=row.payment_date||row.created_at;return date&&new Date(date).getFullYear()===year.value}).map(row=>({id:`payment-${row.id}`,date:row.payment_date||row.created_at||'',lot:'—',customer:customers.value.find(item=>item.id===row.customer_id)?.full_name||'—',block:'—',sold:false,amount:Number(row.amount||0),category:row.payment_category||'Pembayaran',status:row.status})))
const marketingRows=computed(()=>customers.value.filter(row=>row.created_at&&new Date(row.created_at).getFullYear()===year.value).map(row=>({id:`customer-${row.id}`,date:row.created_at||'',lot:'—',customer:row.full_name||'—',block:row.address||'Alamat belum diisi',sold:false,amount:0,category:'Calon Pembeli',status:'Konsumen Baru'})))
const filteredRows=computed(()=>{const source=activeTab.value==='payments'?paymentRows.value:activeTab.value==='marketing'?marketingRows.value:salesRows.value;const needle=search.value.trim().toLocaleLowerCase('id-ID');return source.filter(row=>!needle||[row.lot,row.customer,row.block,row.category,('status' in row ? row.status : '')].join(' ').toLocaleLowerCase('id-ID').includes(needle))})
const visibleRows=computed(()=>filteredRows.value.slice((page.value-1)*5,page.value*5)),pageCount=computed(()=>Math.max(1,Math.ceil(filteredRows.value.length/5)))
watch([activeTab,year,search],()=>{page.value=1})
function height(value:number){const max=Math.max(1,...monthlyBookings.value,...monthlySold.value,...monthlyPayments.value);return value?Math.max(5,value/max*100):0}
function valueHeight(value:number){const max=Math.max(1,...monthlyValue.value);return value?Math.max(5,value/max*100):0}
function currency(value:number){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value)}
function dateLabel(value:string){return value?new Date(value).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'—'}
function exportCsv(){const rows=filteredRows.value;const header=activeTab.value==='payments'?['Tanggal','Kategori','Nama Pembeli','Jumlah','Status']:['Tanggal','Kavling','Nama Pembeli','Blok','Status','Nilai'];const lines=[header,...rows.map(row=>activeTab.value==='payments'?[dateLabel(row.date),row.category,row.customer,row.amount,row.status]:[dateLabel(row.date),row.lot,row.customer,row.block,row.sold?'Terjual':'Booking',row.amount])];const csv=lines.map(line=>line.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`laporan-${activeTab.value}-${year.value}.csv`;anchor.click();URL.revokeObjectURL(url)}
async function loadData(){loading.value=true;error.value='';try{const [lotRows,txResult,customerResult,paymentResult]=await Promise.all([getLots({forceRefresh:true}),supabase.from('lot_transactions').select('id, lot_id, customer_id, status, final_price, created_at, booking_date, sold_date').order('created_at',{ascending:false}).limit(1000),supabase.from('customers').select('id, full_name, address, created_at').limit(1000),supabase.from('payments').select('id, amount, status, payment_category, created_at, payment_date, customer_id').order('created_at',{ascending:false}).limit(1000)]);if(txResult.error)throw txResult.error;if(customerResult.error)throw customerResult.error;if(paymentResult.error)throw paymentResult.error;lots.value=lotRows;transactions.value=(txResult.data||[]) as Transaction[];customers.value=(customerResult.data||[]) as Customer[];payments.value=(paymentResult.data||[]) as Payment[]}catch(cause){error.value=cause instanceof Error?cause.message:'Data laporan gagal dimuat.'}finally{loading.value=false}}
onMounted(()=>{void loadData()})
</script>

<style scoped>
