us:12px;color:var(--text-primary, #252525);background:var(--surface-muted, #f5f3ee)}.summary-grid article:nth-child(3){background:#fff1e5}.summary-grid article:nth-child(4){background:#fff0f0}.summary-icon{display:grid;width:25px;height:25px;place-items:center;border-radius:8px;font-size:15px}.summary-icon.green{color:var(--poliland-green, #355a2c);background:#d8f5e9}.summary-icon.mint{color:var(--poliland-green, #355a2c);background:#dff5ed}.summary-icon.orange{color:#b27c24;background:#ffe2bd}.summary-icon.red{color:#c5232c;background:#ffdddd}.summary-grid strong{font-size:17px;line-height:1}.summary-grid small{color:#5f687b;font-size:9px}.legend{display:flex;justify-content:flex-end;align-items:center;gap:5px;margin:7px 0 3px;color:#645448;font-size:10px}.legend i{width:8px;height:8px;border-radius:50%}.legend .booking,.bars .booking{background:#ffb37b}.legend .sold,.bars .sold{background:#bd201f}.chart{display:grid;height:145px;grid-template-columns:repeat(12,minmax(0,1fr));align-items:end;gap:3px;padding:10px 4px 0;border-bottom:1px solid var(--border-default, #eae7e0)}.chart-col{display:flex;height:100%;min-width:0;flex-direction:column;align-items:center;justify-content:flex-end;gap:5px}.bars{display:flex;width:100%;height:100%;align-items:flex-end;justify-content:center;gap:2px}.bars i{width:37%;min-width:3px;border-radius:3px 3px 0 0}.chart-col small{color:#505d77;font-size:8px}.table-panel .panel-heading{margin-bottom:9px}.search{display:flex;min-height:34px;align-items:center;gap:6px;margin-bottom:9px;padding:0 9px;border-radius:9px;color:#44536d;background:var(--surface-muted, #f5f3ee)}.search ion-icon{font-size:15px}.search input{width:100%;border:0;outline:0;color:var(--text-primary, #252525);background:transparent;font:inherit;font-size:10px}.search input::placeholder{color:#8b92a1}.table-wrap{overflow-x:auto}table{width:100%;min-width:470px;border-collapse:collapse;text-align:left;font-size:9px}th{padding:9px 6px;color:var(--text-primary, #252525);background:#e7efff;white-space:nowrap}td{padding:11px 6px;border-bottom:1px solid #eff1f6;color:#343f56;white-space:nowrap}.lot-number{color:#c29740;font-weight:700}.state-chip{padding:4px 6px;border-radius:99px;font-size:8px}.state-chip.sold{color:#a61e28;background:#ffdadd}.state-chip.booking,.state-chip.pending{color:#94610a;background:#ffe4c8}.state-chip.confirmed{color:#08764f;background:#d6f2e4}.empty{text-align:center;color:#838b99}.table-caption{margin:8px 0 0;color:#665d58;text-align:center;font-size:10px}.pagination{display:flex;justify-content:center;gap:4px;margin-top:7px}.pagination button{min-width:28px;height:28px;border:0;border-radius:8px;color:#35415b;background:var(--surface-muted, #f5f3ee);font:inherit;font-size:10px}.pagination button.active{color:#fff;background:var(--poliland-gold, #cba044)}.pagination button:disabled{opacity:.4}.block-chart{display:grid;height:115px;grid-template-columns:repeat(auto-fit,minmax(36px,1fr));align-items:end;gap:8px;padding:6px 20px 0;border-bottom:1px solid var(--border-default, #eae7e0)}.block-column{display:flex;height:100%;flex-direction:column;align-items:center;justify-content:flex-end;gap:5px}.block-column .bars{gap:3px}.block-column .bars i{width:30%;max-width:12px}.block-column small{color:#65708a;font-size:9px}.value-chart{display:grid;height:98px;grid-template-columns:repeat(12,minmax(0,1fr));margin-top:12px;border-bottom:1px solid var(--border-default, #eae7e0)}.value-col{position:relative;display:flex;justify-content:center}.value-col i{position:absolute;width:8px;height:8px;border:2px solid var(--poliland-gold, #cba044);border-radius:50%;background:#fff}.value-col small{position:absolute;bottom:-14px;color:#65708a;font-size:8px}.export-button{display:flex;width:100%;min-height:36px;align-items:center;justify-content:center;gap:7px;margin-top:10px;border:0;border-radius:10px;color:#a12425;background:#ffdcda;font:inherit;font-size:11px;font-weight:650}.error-state{padding:9px;border-radius:9px;color:#a83838;background:#fff0f0;font-size:11px}.error-state button{border:0;color:#8e6510;background:transparent;font:inherit;font-weight:700}@media(min-width:600px){.owner-shell{gap:18px;padding:22px 24px 120px}.panel{padding:20px}.chart{height:190px}.panel-heading h1,.panel-heading h2{font-size:16px}}
.load-message{margin:8px 0;color:#6d7483;text-align:center;font-size:11px}
