.owner-content{--padding-start:0;--padding-end:0}
.owner-shell{box-sizing:border-box;width:min(100%,760px);min-width:0;overflow-x:clip}
.owner-shell>*{box-sizing:border-box;min-width:0;max-width:100%}
.panel{box-sizing:border-box;min-width:0;width:100%}
.summary-grid{box-sizing:border-box;width:100%;min-width:0;grid-template-columns:repeat(4,minmax(0,1fr))}
.report-tabs{display:grid;width:100%;min-width:0;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;overflow:visible}
.report-tabs button{display:flex;width:100%;min-width:0;flex:initial;justify-content:center;gap:5px;padding:5px 6px;white-space:normal;text-align:center;font-size:10px;line-height:1.2}
.report-tabs button span{min-width:0;overflow-wrap:anywhere}
.report-tabs button ion-icon{flex:0 0 auto}
@media(max-width:380px){.report-tabs{gap:4px}.report-tabs button{gap:3px;padding:5px 3px;font-size:9px}}
@media print{ion-content{--overflow:hidden}.owner-shell{width:100%;padding:0}.report-tabs,.export-panel,.error-state,.pagination,ion-header,ion-footer{display:none!important}.panel{break-inside:avoid;box-shadow:none;border:1px solid #ddd}.table-wrap{overflow:visible}table{min-width:0;font-size:8pt}td,th{white-space:normal}}
</style>
